#!/usr/bin/env bash
# Generated by cloudcc. Pushes each containerised execution unit's image to its ECR
# repository.
#
# This runs *after* `pulumi up`, because the repositories it pushes to do not
# exist until then. `cloudcc deploy` sequences the two for you.
set -euo pipefail

here="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$here"

for tool in docker aws pulumi jq; do
  command -v "$tool" >/dev/null 2>&1 || { echo "push-images.sh: $tool is required" >&2; exit 1; }
done

outputs="$(pulumi stack output --json)"
region="$(pulumi config get aws:region 2>/dev/null || echo "${AWS_REGION:-us-east-1}")"
endpoint_args=()
if [ -n "${CLOUDCC_AWS_ENDPOINT_URL:-}" ]; then
  endpoint_args=(--endpoint-url "$CLOUDCC_AWS_ENDPOINT_URL")
fi

push() {
  local unit="$1" output_key="$2"
  local repo
  repo="$(printf '%s' "$outputs" | jq -r --arg k "$output_key" '.[$k] // empty')"
  if [ -z "$repo" ]; then
    echo "push-images.sh: the stack did not export $output_key; is $unit deployed?" >&2
    return 1
  fi

  local registry="${repo%%/*}"
  echo "logging in to $registry"
  aws ecr "${endpoint_args[@]}" --region "$region" get-login-password \
    | docker login --username AWS --password-stdin "$registry"

  echo "pushing $unit -> $repo:latest"
  docker tag "cloudcc-$unit:latest" "$repo:latest"
  docker push "$repo:latest"
}

push "reporter" "CLOUDCC_ECR_REPORTER_URL"

echo "images pushed; run 'pulumi up' again if a service needs to pick up a new image"
